import sys
sys.path.insert(0, ".")
from video_processing.fighter_tracking.box_smoothing import smooth_track_boxes

def b(cx=500.0, cy=360.0, w=100.0, h=200.0):
    return [cx-w/2, cy-h/2, cx+w/2, cy+h/2]

def det(tid, **kw):
    return {"bbox_xyxy": b(**kw), "confidence": 0.8, "class_id": tid, "model_class_id": tid}

cases = {
    "empty frames list":        {"fps": 50.0, "frames": []},
    "no detections at all":     {"fps": 50.0, "frames": [{"image_name":"f","detections":[]} for _ in range(50)]},
    "single lone detection":    {"fps": 50.0, "frames": [{"image_name":"f","detections":[det(0)] if i==7 else []} for i in range(50)]},
    "track shorter than window":{"fps": 50.0, "frames": [{"image_name":"f","detections":[det(0)] if i<4 else []} for i in range(50)]},
    "two tracks, one clinched": {"fps": 50.0, "frames": [{"image_name":"f","detections":[det(0,cx=480), det(1,cx=520)]} for _ in range(60)]},
    "missing fps key":          {"frames": [{"image_name":"f","detections":[det(0)]} for _ in range(60)]},
    "malformed bbox":           {"fps": 50.0, "frames": [{"image_name":"f","detections":[{"bbox_xyxy":[1,2],"class_id":0}]} for _ in range(30)]},
}

for name, data in cases.items():
    try:
        out = smooth_track_boxes(data)
        n = sum(len(f["detections"]) for f in out.get("frames", []))
        print(f"  OK   {name:<28} -> {n} detections out")
    except Exception as e:
        print(f"  FAIL {name:<28} -> {type(e).__name__}: {e}")
PY
